/**
 * THE E-WAY BILL, AS ITS PDF READS IT - built from the invoice model
 * (toInvoiceModel), so every figure is the invoice's own, laid out as the
 * earlier version's e-Way Bill was:
 *
 *   doc               Doc No. / Date
 *   details           1. E-Way Bill Details - the e-way bill number and date once it is
 *                     generated (empty before), Generated By (the seller's GSTIN),
 *                     Valid Upto (a label only, for now), Mode, Approx Distance,
 *                     Type, Document Details, Transaction type
 *   from / to         2. Address Details - the seller with its dispatch address, the
 *                     buyer with its ship-to address
 *   goods             3. Goods Details - the product lines (a service carries no goods)
 *   totals            Tot. Taxable, CGST, SGST, IGST, Other (everything else on the
 *                     invoice - charges, discount, TCS, round off) and Total Inv. Amt
 *   transport         4. Transportation Details
 *   vehicle           5. Vehicle Details
 *   cancelled         a cancelled e-way bill - the PDF is stamped CANCELLED
 *
 *   toEwayBillModel(invoiceModel, { documentType, ewaybillNo, ewaybillDate, enteredDate, cancelled })
 */

import { toDocumentDate } from '@/Services/salesInvoiceService'

const textOf = (value) => (value === null || value === undefined ? '' : String(value).trim())
const round2 = (value) => Math.round((Number(value) || 0) * 100) / 100

/** A figure as the e-way bill prints it - "1500.0", "37.5", "2.5". */
export const ewbNumber = (value) => {
  const number = round2(value)
  return Number.isInteger(number) ? number.toFixed(1) : String(number)
}

const sameText = (a, b) => textOf(a).toLowerCase() === textOf(b).toLowerCase()

/**
 * The e-way bill's transaction type - from whether the goods go to the buyer's
 * own address and leave from the seller's own (the four types the portal has).
 */
const transactionTypeOf = (model) => {
  const shipsElsewhere = Boolean(textOf(model.shipping.address)) && !sameText(model.shipping.address, model.buyer.address)
  const dispatchedElsewhere = Boolean(textOf(model.dispatch.address)) && !sameText(model.dispatch.address, model.seller.address)
  if (shipsElsewhere && dispatchedElsewhere) return 'COMBINATION OF 2 AND 3'
  if (shipsElsewhere) return 'BILL TO - SHIP TO'
  if (dispatchedElsewhere) return 'BILL FROM - DISPATCH FROM'
  return 'REGULAR'
}

/** A Credit Note brings goods back (a sales return); every other type sends them out. */
const supplyTypeOf = (documentType) => (sameText(documentType, 'Credit Note') ? 'Inward-Sales-Return' : 'Outward-supply-Regular')

const addressOf = (party, extra = []) => [party.address, ...extra].map(textOf).filter(Boolean).join(', ')

export function toEwayBillModel(model, { documentType = '', ewaybillNo = '', ewaybillDate = '', enteredDate = '', cancelled = false } = {}) {
  const documentDate = toDocumentDate(model.invoice.invoiceDate) || textOf(model.invoice.invoiceDate)
  const goods = model.lines.filter((line) => line.kind === 'product' && !line.service)
  const taxable = round2(goods.reduce((sum, line) => sum + (line.netTaxable ?? line.taxable), 0))
  const cgst = round2(goods.reduce((sum, line) => sum + line.cgst, 0))
  const sgst = round2(goods.reduce((sum, line) => sum + line.sgst, 0))
  const igst = round2(goods.reduce((sum, line) => sum + line.igst, 0))
  const total = round2(model.totals.grandTotal)
  const interState = model.totals.anyIgst && !model.totals.anySplit

  const description = (line) => {
    const name = textOf(line.productName || line.name)
    const extra = textOf(line.description)
    return extra ? `${name} (${extra})` : name
  }
  const rates = (line) => (interState ? [0, 0, line.gst] : [line.gst / 2, line.gst / 2, 0]).map(ewbNumber).join(' + ')

  const transporter = [model.invoice.transporterId, model.invoice.dispatchThrough].map(textOf).filter(Boolean).join(' ')
  const distance = textOf(model.invoice.distance).replace(/\s+/g, '')

  return {
    title: 'e-Way Bill',
    doc: { no: textOf(model.invoice.invoiceNo), date: documentDate },
    details: {
      ewaybillNo: textOf(ewaybillNo),
      generatedDate: toDocumentDate(ewaybillDate) || textOf(ewaybillDate) || documentDate,
      generatedBy: textOf(model.seller.gstin),
      // A label only for now - the portal's validity is not printed yet.
      validUpto: '',
      mode: textOf(model.invoice.deliveryMode),
      distance,
      type: supplyTypeOf(documentType),
      documentDetails: textOf(model.invoice.invoiceNo),
      transactionType: transactionTypeOf(model),
    },
    from: {
      gstin: textOf(model.seller.gstin),
      name: textOf(model.seller.name),
      state: textOf(model.seller.state),
      address: addressOf(model.dispatch.address ? model.dispatch : model.seller, []),
    },
    to: {
      gstin: textOf(model.buyer.gstin),
      name: textOf(model.buyer.name),
      state: textOf(model.buyer.state),
      address: model.shipping.address
        ? addressOf(model.shipping, [model.shipping.state, model.shipping.pincode])
        : addressOf(model.buyer, [model.buyer.state, model.buyer.pincode]),
    },
    goods: goods.map((line) => ({
      key: String(line.id),
      hsn: textOf(line.hsn),
      description: description(line),
      quantity: [ewbNumber(line.quantity), textOf(line.per).toUpperCase()].filter(Boolean).join(' '),
      taxable: ewbNumber(line.netTaxable ?? line.taxable),
      rates: rates(line),
    })),
    totals: {
      taxable: ewbNumber(taxable),
      cgst: ewbNumber(cgst),
      sgst: ewbNumber(sgst),
      igst: ewbNumber(igst),
      // Whatever else the invoice total carries - other charges and their tax, discount, TCS, round off.
      other: String(round2(total - taxable - cgst - sgst - igst)),
      total: ewbNumber(total),
    },
    transport: {
      transporter: transporter || 'SELF',
      docNo: textOf(model.invoice.lrNo),
      docDate: toDocumentDate(model.invoice.lrDate) || documentDate,
    },
    vehicle: {
      mode: textOf(model.invoice.deliveryMode),
      vehicleNo: textOf(model.invoice.vehicleNo),
      from: textOf(model.dispatch.state) || textOf(model.seller.state),
      enteredDate: toDocumentDate(enteredDate) || textOf(enteredDate) || documentDate,
      enteredBy: textOf(model.seller.name),
    },
    cancelled: Boolean(cancelled),
  }
}
